import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../db/isar/main_db.dart';
import '../../../models/isar/models/contract.dart';
import '../../../providers/wallet/public_private_balance_state_provider.dart';
import '../../../themes/stack_colors.dart';
import '../../../utilities/amount/amount.dart';
import '../../../utilities/amount/amount_formatter.dart';
import '../../../utilities/compact_amount.dart';
import '../../../utilities/text_styles.dart';
import '../../../utilities/util.dart';
import '../../../wallets/crypto_currency/coins/solana.dart';
import '../../../wallets/isar/providers/eth/token_balance_provider.dart';
import '../../../wallets/isar/providers/solana/sol_token_balance_provider.dart';
import '../../../wallets/isar/providers/wallet_info_provider.dart';

class WalletInfoRowBalance extends ConsumerWidget {
  const WalletInfoRowBalance({
    super.key,
    required this.walletId,
    this.contractAddress,
    this.balanceType,
  });

  final String walletId;
  final String? contractAddress;
  final BalanceType? balanceType;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final info = ref.watch(pWalletInfo(walletId));

    final Amount totalBalance;
    Contract? contract;

    if (contractAddress == null) {
      totalBalance = balanceType == BalanceType.private
          ? info.cachedBalanceSecondary.total + info.cachedBalanceTertiary.total
          : balanceType == BalanceType.public
          ? info.cachedBalance.total
          : info.cachedBalance.total +
                info.cachedBalanceSecondary.total +
                info.cachedBalanceTertiary.total;

      contract = null;
    } else {
      // Check if it's a Solana wallet.
      if (info.coin is Solana) {
        contract = MainDB.instance.getSolContractSync(contractAddress!);
        if (contract != null) {
          final solanaTokenInfo = ref.watch(
            pSolanaTokenWalletInfo((
              walletId: walletId,
              tokenMint: contractAddress!,
            )),
          );
          totalBalance = solanaTokenInfo.getCachedBalance().total;
        } else {
          // Token not yet in database, show zero balance.
          totalBalance = Amount(rawValue: BigInt.zero, fractionDigits: 0);
        }
      } else {
        // Ethereum token.
        contract = MainDB.instance.getEthContractSync(contractAddress!);
        if (contract != null) {
          totalBalance = ref
              .watch(
                pTokenBalance((
                  walletId: walletId,
                  contractAddress: contractAddress!,
                )),
              )
              .total;
        } else {
          // Contract not yet in database, show zero balance.
          totalBalance = Amount(rawValue: BigInt.zero, fractionDigits: 0);
        }
      }
    }

    // A wallet whose balance has never been computed says so, instead of
    // showing a zero it does not know to be true.
    //
    // cachedBalanceString is null until a sync has actually summed the UTXOs,
    // and cachedBalance turns that null into Balance.zeroFor(). On this row
    // that became a confident "0.00 PEP", indistinguishable from an empty
    // wallet. A pool address with 45,376 transactions takes minutes to reach
    // its first balance, and the detail screen shows a Syncing chip through
    // it while this row quietly claimed the wallet was empty.
    //
    // Only the never-computed case. A real zero stays a zero, and a stale
    // balance keeps showing while a later sync runs, because a number from
    // ten minutes ago is worth more than a spinner.
    if (contractAddress == null && info.cachedBalanceString == null) {
      return Text(
        goTr(context, "Syncing…"),
        style: Util.isDesktop
            ? STextStyles.desktopTextExtraSmall(context).copyWith(
                color: Theme.of(
                  context,
                ).extension<StackColors>()!.textSubtitle1,
              )
            : STextStyles.itemSubtitle(context),
      );
    }

    // Every other balance surface in the app protects itself from a long
    // number and this one did not: a bare Text in a fixed-height row, so at
    // maximum precision 4,946,671,530.20654321 PEP wrapped to a second line
    // the row had no room for and came out clipped. Same treatment as the
    // hero, dropping the sub-coin dust past eight whole digits and keeping
    // the magnitude exact, with scale-down as the backstop for whatever the
    // rule still lets through.
    final formatter = ref.watch(pAmountFormatter(info.coin));
    final numStr = formatter.format(
      totalBalance,
      tokenContract: contract,
      withUnitName: false,
    );
    final unit = contract?.symbol ?? info.coin.ticker;
    final label = "${withoutDustDecimals(numStr) ?? numStr} $unit";

    return FittedBox(
      fit: BoxFit.scaleDown,
      alignment: Alignment.centerLeft,
      child: Text(
        label,
        maxLines: 1,
        style: Util.isDesktop
            ? STextStyles.desktopTextExtraSmall(context).copyWith(
                color: Theme.of(
                  context,
                ).extension<StackColors>()!.textSubtitle1,
              )
            : STextStyles.itemSubtitle(context),
      ),
    );
  }
}
